    "ja": {
      "published_parent": {
        "selected_full_original_parent": [
          "アブー・サイード・アル＝フドゥリー（彼にアッラーのご満悦あれ）によれば、アッラーの使徒（彼にアッラーからの祝福と平安あれ）は言いました：「・・・そして（アッラーから）忍耐を授かることを求める者は、アッラーが忍耐を授けて下さるであろう。そして人が与えられるものの内、忍耐ほど良く、かつ活用範囲の広いものはない。」（アル＝ブハーリーとムスリムの伝承3）"
        ]
      },
      "source": "EXACT-PUBLISHED-SELECTIONS-AND-COMPLETE-CONTEXT.json",
      "source_uri": null,
